from pathlib import Path
import json,statistics as s
R=Path(__file__).resolve().parent;rows=[json.loads(x) for x in (R/'COLD_WARM_RESULTS.jsonl').read_text().splitlines()];report=[]
for case in ['nonbest','charge_required','equality']:
 for method in ['flat','hier']:
  selected=[x for x in rows if x['case_id']==case and x['method']==method and x['status']=='pass'];cold=sorted([x for x in selected if x['condition'].startswith('cold')],key=lambda x:x['repeat']);warm=sorted([x for x in selected if x['condition'].startswith('warm')],key=lambda x:x['repeat'])
  report.append(dict(case=case,method=method,paired_repeats=len(cold),median_cold_over_warm_solver_wall=s.median(a['measured']['solver_wall_ns']/b['measured']['solver_wall_ns'] for a,b in zip(cold,warm)),cold_source_runs=[x['measured']['engine_routing_delta']['source_runs'] for x in cold],warm_source_runs=[x['measured']['engine_routing_delta']['source_runs'] for x in warm],median_cold_solver_ms=s.median(x['measured']['solver_wall_ns'] for x in cold)/1e6,median_warm_solver_ms=s.median(x['measured']['solver_wall_ns'] for x in warm)/1e6,median_warmup_solver_ms=s.median(x['warmup']['solver_wall_ns'] for x in warm)/1e6))
report=dict(scheduled=len(rows),passed=sum(x['status']=='pass' for x in rows),measured_solver_wall_seconds=sum(x['measured']['solver_wall_ns'] for x in rows)/1e9,measured_audit_wall_seconds=sum(x['measured']['audit_wall_ns'] for x in rows)/1e9,warmup_solver_wall_seconds=sum(x['warmup']['solver_wall_ns'] for x in rows if x['warmup'])/1e9,warmup_audit_wall_seconds=sum(x['warmup']['audit_wall_ns'] for x in rows if x['warmup'])/1e9,setup_wall_seconds=sum(x['setup_ns'] for x in rows)/1e9,peak_worker_rss_kib=max(x['peak_rss_kib'] for x in rows),rows=report,note='Tiny synthetic Python router, selected-leg cache only. CPU deltas may quantize to zero at these durations; do not infer zero routing CPU cost. Warmup and initial preparation excluded from measured query latency but reported separately; no long-haul speedup claim.')
(R/'COLD_WARM_ANALYSIS.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items() if k!='rows'}))
